<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch,nextTick,computed} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {Search,Maximize2,List,Network,ArrowUpRight,Link2,Plus,Check,Bookmark,MousePointer2} from 'lucide-vue-next'
import {api,safeUrl} from '../api'
import type {MapData,MapNode,MapEdge} from '../types'
import {useApp} from '../stores/app'
import Notice from '../components/Notice.vue'
import * as echarts from 'echarts/core'
import {GraphChart} from 'echarts/charts'
import {TooltipComponent} from 'echarts/components'
import {CanvasRenderer} from 'echarts/renderers'
echarts.use([GraphChart,TooltipComponent,CanvasRenderer])
const app=useApp(),router=useRouter(),route=useRoute(),data=ref<MapData|null>(null),loading=ref(true),error=ref(''),scope=ref('all'),discipline=ref(String(route.query.discipline||'')),query=ref(''),list=ref(window.matchMedia('(max-width: 760px)').matches),selected=ref<MapNode|null>(null),selectedEdge=ref<MapEdge|null>(null),rootNotice=ref(''),graph=ref<HTMLElement|null>(null)
let chart:echarts.ECharts|null=null,observer:ResizeObserver|null=null,themeObserver:MutationObserver|null=null,searchTimer:ReturnType<typeof setTimeout>|undefined,seq=0
const edgesForNode=computed(()=>selected.value?data.value?.edges.filter(e=>e.source===selected.value?.id||e.target===selected.value?.id)||[]:[]),visibleTopics=computed(()=>data.value?.nodes.filter(n=>n.type==='topic')||[])
function nodeName(id:string){return data.value?.nodes.find(x=>x.id===id)?.name||id}
async function load(root='',merge=true){
 const request=++seq;loading.value=true;error.value='';rootNotice.value=''
 try{
  const params=new URLSearchParams({scope:scope.value,limit:'80',depth:'1'})
  if(discipline.value)params.set('discipline',discipline.value)
  if(query.value.trim())params.set('q',query.value.trim())
  if(root)params.set('root',root)
  let res=await api<MapData>(`/map?${params}`)
  if(request!==seq)return
  const rootId=root.startsWith('topic:')||root.startsWith('discipline:')||root.startsWith('subfield:')?root:'topic:'+root
  if(root&&!merge&&!res.nodes.some(n=>n.id===rootId)){
   params.delete('root');res=await api<MapData>(`/map?${params}`)
   if(request!==seq)return
   rootNotice.value='当前范围未找到指定主题，已展示知识库地图。可以清除筛选后继续探索。'
  }
  if(root&&merge&&data.value){
   const nodes=new Map(res.nodes.map(x=>[x.id,x])),edges=new Map([...data.value.edges,...res.edges].map(x=>[x.id,x]))
   data.value.nodes.forEach(node=>{if(!nodes.has(node.id))nodes.set(node.id,node)})
   const limited=[...nodes.values()].slice(0,150),ids=new Set(limited.map(x=>x.id))
   data.value={...res,nodes:limited,edges:[...edges.values()].filter(e=>ids.has(e.source)&&ids.has(e.target)).slice(0,300),truncated:res.truncated||nodes.size>150}
  }else{data.value=res;selected.value=root?res.nodes.find(n=>n.id===rootId)||null:null;selectedEdge.value=null}
  await nextTick();if(request===seq)draw()
 }catch(e){if(request===seq)error.value=e instanceof Error?e.message:'地图未能加载'}
 finally{if(request===seq)loading.value=false}
}
function loadRouteRoot(){return load(typeof route.query.root==='string'?route.query.root:'',false)}
function draw(){if(list.value||!graph.value||!data.value)return;if(!chart){chart=echarts.init(graph.value,undefined,{renderer:'canvas'});chart.on('click',(params)=>{const payload=params.data as {id?:string};if(params.dataType==='edge'){selectedEdge.value=data.value?.edges.find(e=>e.id===payload?.id)||null;selected.value=null}else{selected.value=data.value?.nodes.find(n=>n.id===payload?.id)||null;selectedEdge.value=null;if(selected.value)void load(selected.value.id)}});chart.on('dblclick',params=>{const n=data.value?.nodes.find(n=>n.id===(params.data as {id:string}).id);if(n?.topic_id)void router.push(`/topics/${n.topic_id}`)});observer=new ResizeObserver(()=>chart?.resize());observer.observe(graph.value)}const dark=document.documentElement.classList.contains('dark');chart.setOption({animation:!window.matchMedia('(prefers-reduced-motion: reduce)').matches,tooltip:{show:true,formatter:(p:{dataType:string;data:{name?:string;label?:string;type?:string}})=>String(p.dataType==='edge'?p.data.label||p.data.type:p.data.name||'').replace(/[<>]/g,'')},series:[{type:'graph',layout:'force',roam:true,draggable:true,zoom:.78,scaleLimit:{min:.2,max:4},force:{repulsion:330,edgeLength:[70,130],gravity:.07},label:{show:true,position:'bottom',color:dark?'#d9ded9':'#4b544c',fontFamily:'sans-serif',fontSize:11},edgeSymbol:['none','none'],lineStyle:{color:dark?'#52615a':'#c9d1c6',width:1.2,curveness:.12},emphasis:{focus:'adjacency',lineStyle:{width:2.8},label:{fontWeight:'bold'}},data:data.value.nodes.map(n=>({id:n.id,name:n.name,symbolSize:n.type==='discipline'?45+Math.min(n.count||0,15):n.type==='subfield'?21:n.explored?17:12,itemStyle:{color:n.color||'#648879',opacity:n.explored||n.type!=='topic'?1:.52,borderWidth:n.bookmarked?3:n.explored?2:0,borderColor:n.bookmarked?'#c99a46':dark?'#f6f5f0':'#263e32'},label:{fontWeight:n.type==='discipline'?'bold':'normal',fontSize:n.type==='discipline'?13:11}})),links:data.value.edges.map(e=>({id:e.id,source:e.source,target:e.target,name:e.label,label:e.label,type:e.type,symbol:['none',e.type==='taxonomy'||e.direction==='both'?'none':'arrow'],lineStyle:{type:e.type==='analogy'?'dashed':'solid'}}))}]},true)}
function toggleList(){list.value=!list.value;if(list.value){observer?.disconnect();chart?.dispose();chart=null}else nextTick(draw)}
function resetView(){chart?.dispatchAction({type:'restore'});draw()}
function selectNode(n:MapNode){selected.value=n;selectedEdge.value=null}
watch([scope,discipline],()=>void loadRouteRoot());watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>void loadRouteRoot(),350)})
watch(()=>route.query.root,()=>void loadRouteRoot())
onMounted(()=>{void loadRouteRoot();themeObserver=new MutationObserver(draw);themeObserver.observe(document.documentElement,{attributes:true,attributeFilter:['class']})});onBeforeUnmount(()=>{++seq;clearTimeout(searchTimer);observer?.disconnect();themeObserver?.disconnect();chart?.dispose()})
</script>
<template><div class="map-page"><header class="page-heading"><div><p class="eyebrow">A WORLD OF CONNECTIONS</p><h1>认知地图<span class="serif-accent">.</span></h1><p>每一个新知识，都可能是通向另一个领域的桥。</p></div><div class="page-heading-note"><Network :size="24"/><span>知识库中的真实节点<br>由你的探索逐渐点亮</span></div></header><section class="map-toolbar" aria-label="地图筛选"><label class="search-field"><Search :size="17"/><input v-model="query" placeholder="搜索主题或领域" aria-label="搜索主题或领域" maxlength="100"></label><select v-model="discipline" aria-label="按学科筛选"><option value="">所有主学科</option><option v-for="d in app.disciplines" :key="d.id" :value="d.id">{{d.name}}</option></select><div class="scope-tabs" role="group" aria-label="地图范围"><button @click="scope='all'" :class="{selected:scope==='all'}" :aria-pressed="scope==='all'">知识库范围</button><button @click="scope='explored'" :class="{selected:scope==='explored'}" :aria-pressed="scope==='explored'">我的探索</button></div><button class="button outline small" @click="toggleList"><Network v-if="list" :size="15"/><List v-else :size="15"/>{{list?'图谱视图':'列表视图'}}</button></section><Notice v-if="error" :error="error" @retry="loadRouteRoot()"/><p v-if="rootNotice" class="soft-notice" role="status">{{rootNotice}}</p><div class="map-layout"><section class="map-canvas-shell"><div v-if="loading" class="map-loading" role="status">正在读取知识关系…</div><div v-if="!list" ref="graph" class="map-canvas" role="img" aria-label="可缩放和拖动的知识关系图。也可切换列表视图使用键盘浏览。"/><div v-else class="map-list"><div class="map-list-heading"><h2>{{scope==='explored'?'已探索的主题':'知识库中的主题'}}</h2><span>{{visibleTopics.length}} 个主题</span></div><button v-for="node in data?.nodes" :key="node.id" :class="['map-list-item',{selected:selected?.id===node.id}]" @click="selectNode(node)"><i :style="{background:node.color}"/><span><strong>{{node.name}}</strong><small>{{node.type==='discipline'?'一级学科':node.type==='subfield'?'细分领域':'主题'}}<span v-if="node.explored"> · 已探索</span><span v-if="node.bookmarked"> · 已收藏</span></small></span><ArrowUpRight :size="15"/></button><Notice v-if="!loading&&!data?.nodes.length" empty="当前筛选下没有节点。尝试切换到知识库范围，或清除搜索。"/></div><button v-if="!list" class="icon-button map-fit" aria-label="重置地图视角" @click="resetView"><Maximize2 :size="18"/></button><div v-if="!list" class="map-hint"><MousePointer2 :size="13"/>滚轮缩放 · 拖动节点 · 点击展开 · 双击主题进入详情</div></section><aside class="map-inspector"><template v-if="selected"><span class="tiny-label">{{selected.type==='discipline'?'DISCIPLINE':selected.type==='subfield'?'SUBFIELD':'KNOWLEDGE NODE'}}</span><div class="inspector-title"><i :style="{background:selected.color}"/><h2>{{selected.name}}</h2></div><p>{{selected.description||'这个节点来自当前知识库。沿着有依据的关系，继续探索。'}}</p><div class="node-status"><span v-if="selected.explored"><Check :size="12"/>已探索</span><span v-if="selected.bookmarked"><Bookmark :size="12"/>已收藏</span><span v-if="selected.learning==='understood'">自述已理解</span><span v-else-if="selected.learning==='learning'">正在学习</span><span v-if="!selected.explored&&selected.type==='topic'">尚未探索</span></div><RouterLink v-if="selected.topic_id" :to="`/topics/${selected.topic_id}`" class="button primary full">阅读主题<ArrowUpRight :size="15"/></RouterLink><button class="button outline full" @click="load(selected.id)" :disabled="loading"><Plus :size="15"/>展开周围节点</button><div class="inspector-relations"><span class="tiny-label">RELATIONS & EVIDENCE</span><div v-for="edge in edgesForNode" :key="edge.id" class="inspector-relation"><button class="text-button" @click="selectedEdge=edge;selected=null"><Link2 :size="13"/>{{edge.label||edge.type}}</button><p>{{nodeName(edge.source)}} → {{nodeName(edge.target)}}</p><small>{{edge.explanation}}</small></div><p v-if="!edgesForNode.length" class="muted">当前子图中没有更多可用关系。</p></div></template><template v-else-if="selectedEdge"><span class="tiny-label">RELATION EVIDENCE</span><h2>{{selectedEdge.label||selectedEdge.type}}</h2><p class="edge-endpoints">{{nodeName(selectedEdge.source)}}<ArrowUpRight :size="16"/>{{nodeName(selectedEdge.target)}}</p><span class="source-chip">关系类型：{{selectedEdge.type}}</span><p>{{selectedEdge.explanation||'该关系当前没有额外说明。'}}</p><a v-if="selectedEdge.source_url" :href="safeUrl(selectedEdge.source_url)" target="_blank" rel="noopener noreferrer" class="text-button">查看关系依据 <ArrowUpRight :size="14"/></a><p v-else class="privacy-note">学科归属关系由知识库分类映射维护，属于编目关系。</p></template><template v-else><div class="inspector-empty"><div class="mini-network"><span/><span/><span/></div><span class="eyebrow">FOLLOW A CONNECTION</span><h2>知识的边界，<br>藏着新的入口。</h2><p>选择一个节点，查看简介和状态；选择一条连线，了解它为什么存在。</p><p>每条连线都保留关系类型。启发性类比不等于事实关系。</p></div></template><div class="map-legend"><span class="tiny-label">HOW TO READ THIS MAP</span><p><i class="legend-large"/>大节点：学科 · 大小随已探索数变化</p><p><i class="legend-small"/>小节点：细分领域与主题</p><p><i class="legend-explored"/>描边：已探索 · 金色描边：收藏</p><p>颜色区分主学科；未探索主题降低饱和度。关系箭头与说明按记录的起点到终点阅读。</p></div></aside></div><div class="map-bottom"><span>{{data?.nodes.length||0}} 个节点 · {{data?.edges.length||0}} 条关系</span><span v-if="data?.truncated">当前展示有限子图，点击节点按需展开。最多显示 150 个节点。</span><span v-else>仅展示当前知识库范围，不代表全部人类知识。</span></div><div class="discipline-legend"><span v-for="d in app.disciplines" :key="d.id"><i :style="{background:d.color}"/>{{d.name}}</span></div></div></template>
